package compiler.Code_generation;

import compiler.Lexer.Symbols.Symbols;
import compiler.Parser.*;
import compiler.Parser.TreeStructure.CustomNode;
import org.objectweb.asm.ClassWriter;
import org.objectweb.asm.MethodVisitor;
import org.objectweb.asm.Opcodes;

import java.lang.reflect.InvocationTargetException;

public class Compiler implements CodeGenerationVisitor {

    private ClassWriter cw;
    private MethodVisitor mv;

    public void generateByteCode(StartingPoint startingPoint) {
        final String className = "Test";
        cw = new ClassWriter(ClassWriter.COMPUTE_FRAMES);
        cw.visit(Opcodes.V11, Opcodes.ACC_PUBLIC + Opcodes.ACC_SUPER, className, null, "java/lang/Object", null);

        // Generate main method
        mv = cw.visitMethod(Opcodes.ACC_PUBLIC + Opcodes.ACC_STATIC, "main", "([Ljava/lang/String;)V", null, null);
        mv.visitCode();

        startingPoint.acceptCodeGeneration(this);

        // Add return instruction
        mv.visitInsn(Opcodes.RETURN);
        mv.visitEnd();
        mv.visitMaxs(1, 1);

        cw.visitEnd();

        byte[] byteCode = cw.toByteArray();
        ByteArrayClassLoader loader = new ByteArrayClassLoader();
        Class<?> test = loader.defineClass(className, byteCode);
        try {
            test.getMethod("main", String[].class).invoke(null, (Object) new String[0]);
        } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
            e.printStackTrace();
        }
    }

    private int getLoadOpcode(Type type) {
        String valueType = type.getType().getValue();
        if (valueType.equals("int")  ||  valueType.equals("bool")) {
            return Opcodes.ILOAD;
        } else if (valueType.equals("real") ){
            return Opcodes.DLOAD;
        } else if (valueType.equals("string")) {
            return Opcodes.ALOAD;
        } else {
            return 0; // Handle other types as needed
        }
    }

    private int getStoreOpcode(Type type) {
        String valueType = type.getType().getValue();
        if (valueType.equals("int")  ||  valueType.equals("bool")) {
            return Opcodes.ISTORE;
        } else if (valueType.equals("real") ){
            return Opcodes.DSTORE;
        } else if (valueType.equals("string")) {
            return Opcodes.ASTORE;
        } else {
            return 0; // Handle other types as needed
        }
    }

    private String getDescriptor(Type type) {
        String valueType = type.getType().getValue();
        if (valueType.equals("int")) {
            return "I";
        } else if (valueType.equals("real")) {
            return "F";
        } else if (valueType.equals("bool")) {
            return "Z";
        } else if (valueType.equals("string")) {
            return "Ljava/lang/String;";
        } else {
            // Handle other types as needed
            return "";
        }
    }


    public static void main(String[] args) {
        System.out.println("Hello from the compiler !");
    }

    @Override
    public void visit(StartingPoint node) {
        for (Constante c : node.getConstante()) {
            c.acceptCodeGeneration(this);
        }
        for (Records r : node.getRecords()) {
            r.acceptCodeGeneration(this);
        }
        for (Procedure p : node.getProcedures_list()) {
            p.acceptCodeGeneration(this);
        }
        for (BlockStatement b : node.getBlockStatement_list()) {
            b.acceptCodeGeneration(this);
        }
    }

    @Override
    public void visit(AccessingData node) {
        node.getChildren().forEach(elements -> elements.acceptCodeGeneration(this));

        if (node.getIndexOrRecords() != null) {
            node.getIndexOrRecords().acceptCodeGeneration(this);
        }
        if (node.getOptionalRecord() != null) {
            node.getOptionalRecord().acceptCodeGeneration(this);
        }
    }

    @Override
    public void visit(ArrayInit node) {
        node.getChildren().forEach(elements -> elements.acceptCodeGeneration(this));
        Symbols type = node.getType();
        Operation size = node.getSize();
        //TODO
    }

    @Override
    public void visit(Assignement node) {
        if (node.getExpr() != null) {
            node.getExpr().acceptCodeGeneration(this);
        }

        if (node.getVariable() instanceof AccessingData) {
            AccessingData accessingData = (AccessingData) node.getVariable();
            accessingData.acceptCodeGeneration(this);
            mv.visitFieldInsn(Opcodes.PUTSTATIC, "Test", accessingData.getElements().getValue(), accessingData.getElements().getToken());
        } else {
            // Handle assignment to a local or global variable
            String varName = node.getType().getIdentifier().getValue();
            int opCode = getStoreOpcode(node.getType());
            mv.visitVarInsn(opCode, varName.hashCode());
        }
    }
    public void visit(BlockStatement node) {
        node.getStatements().forEach(statement -> statement.acceptCodeGeneration(this));
    }

    @Override
    public void visit(BuiltInFunction node) {

    }

    @Override
    public void visit(Constante node) {
        // Visit the assignment node to generate bytecode for initializing the constant
        node.getAssignement().acceptCodeGeneration(this);

        // Store the value of the constant into a field
        String fieldName = node.getAssignement().getType().getIdentifier().getValue();
        Type fieldType = node.getAssignement().getType();

        // Generate the field declaration
        //cw.visitField(Opcodes.ACC_PUBLIC + Opcodes.ACC_STATIC, fieldName, fieldType.getType().getValue(), null, null).visitEnd();
        String fieldTypeSignature = getDescriptor(fieldType);
        cw.visitField(Opcodes.ACC_PUBLIC + Opcodes.ACC_STATIC, fieldName, fieldTypeSignature, null, null).visitEnd();

        // Generate the field assignment bytecode
        mv.visitFieldInsn(Opcodes.PUTSTATIC, "Test", fieldName, fieldTypeSignature);
    }

    @Override
    public void visit(ControlStructure node) {

    }

    @Override
    public void visit(Expressions node) {

    }

    @Override
    public void visit(GlobalVariable node) {
        //node.getAssignement().acceptCodeGeneration(this);
        String varName = node.getAssignement().getType().getType().getValue();
        String type = node.getAssignement().getType().getIdentifier().getValue();
        mv.visitFieldInsn(Opcodes.GETSTATIC, "Test", varName, type);
    }

    @Override
    public void visit(InOutFunction node) {

    }

    @Override
    public void visit(NewRecord node) {
        node.getChildren().forEach(record -> record.acceptCodeGeneration(this));
    }

    @Override
    public void visit(Numbers node) {
        mv.visitLdcInsn(node.getNumber().getValue());
    }

    @Override
    public void visit(Procedure node) {
        String procName = node.getName().getValue();
        node.getParameters().forEach(param -> param.acceptCodeGeneration(this));

        node.getReturnType().acceptCodeGeneration(this);
        Type returnType = node.getReturnType();

        node.getBlockStatement().acceptCodeGeneration(this);
        BlockStatement statement = node.getBlockStatement();
    }

    @Override
    public void visit(Records node) {
        node.getBlockRecord().forEach(recordType -> recordType.acceptCodeGeneration(this));
    }

    @Override
    public void visit(Type node) {
        node.getChildren().forEach(param -> param.acceptCodeGeneration(this));
    }

    @Override
    public void visit(Operation operation) {
        for (CustomNode op : operation.get_list_operation()) {
            op.acceptCodeGeneration(this);
        }
        for (CustomNode factor : operation.get_list_factors()) {
            factor.acceptCodeGeneration(this);
        }
        for (CustomNode operator : operation.get_list_operators()) {
            operator.acceptCodeGeneration(this);
        }
    }
}
